import Foundation
import StorageSigning
import Testing

/// Reference vectors generated by `scripts/vectors/generate_signing_vectors.py` with the official SDKs
/// (botocore, alibabacloud-oss-v2 cross-checked with oss2, oss2 for V1). Nothing in these files is hand-written.
struct VectorFile<Case: Decodable & Sendable>: Decodable, Sendable {
    struct Credential: Decodable, Sendable {
        let accessKeyID: String
        let secretAccessKey: String
        let sessionToken: String?
    }

    let credentials: [String: Credential]
    let cases: [Case]
    let sdks: [String: String]

    func signingCredentials(_ name: String) throws -> SigningCredentials {
        guard let credential = credentials[name] else { throw VectorError.missingCredential(name) }
        return SigningCredentials(accessKeyID: credential.accessKeyID, secretAccessKey: credential.secretAccessKey,
                                  sessionToken: credential.sessionToken)
    }
}

enum VectorError: Error {
    case missingFile(String)
    case missingCredential(String)
    case badTimestamp(String)
}

struct AWSHeaderCase: Decodable, Sendable, CustomTestStringConvertible {
    struct Expected: Decodable, Sendable {
        let encodedPath: String
        let canonicalRequest: String
        let stringToSign: String
        let signature: String
        let authorization: String
        let payloadHash: String?
        let amzDate: String?
        let securityToken: String?
    }

    let name: String
    let credentials: String
    let region: String
    let method: String
    let scheme: String
    let host: String
    let path: String
    let query: [[String]]?
    let headers: [[String]]?
    let body: String?
    let unsignedPayload: Bool?
    let awsDoc: Bool?
    let documentedSignature: String?
    let url: String
    let timestamp: String
    let expected: Expected

    var testDescription: String { name }
}

