enum Vectors {
    static func load<Case: Decodable & Sendable>(_ name: String, as type: Case.Type = Case.self) throws -> VectorFile<Case> {
        guard let url = Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures") else {
            throw VectorError.missingFile(name)
        }
        return try JSONDecoder().decode(VectorFile<Case>.self, from: Data(contentsOf: url))
    }

    static let awsHeader: VectorFile<AWSHeaderCase>? = try? load("aws-sigv4-header")
    static let awsPresign: VectorFile<AWSPresignCase>? = try? load("aws-sigv4-presign")
    static let ossV4: VectorFile<OSSV4Case>? = try? load("oss-v4")
    static let ossV1: VectorFile<OSSV1Case>? = try? load("oss-v1")

    /// Parses `yyyyMMdd'T'HHmmss'Z'` (UTC).
    static func date(_ timestamp: String) throws -> Date {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(identifier: "UTC")
        formatter.dateFormat = "yyyyMMdd'T'HHmmss'Z'"
        guard let date = formatter.date(from: timestamp) else { throw VectorError.badTimestamp(timestamp) }
        return date
    }

    static func parameters(_ pairs: [[String]]?) -> [QueryParameter] {
        (pairs ?? []).compactMap { pair in
            guard let name = pair.first else { return nil }
            return QueryParameter(name, pair.count > 1 ? pair[1] : "")
        }
    }

    static func headers(_ pairs: [[String]]?, excluding excluded: Set<String> = []) -> [HTTPHeader] {
        (pairs ?? []).compactMap { pair in
            guard pair.count == 2, !excluded.contains(pair[0].lowercased()) else { return nil }
            return HTTPHeader(pair[0], pair[1])
        }
    }
}
